/* Divide the double width number (d1|d0) by the divisor. (d1|d0 / div)
 *
 * Assumes divisor has highest bit set.
 *
 * @param [in] d1   The high order half of the number to divide.
 * @param [in] d0   The low order half of the number to divide.
 * @param [in] div  The divisor.
 *
 * @return  The result of the division.
 */
static sp_digit div_4096_word_64(sp_digit d1, sp_digit d0, sp_digit div)
{
    __asm__ __volatile__ (
        /* Divisor to estimate with - high half plus one. */
        "srli    t5, %[div], 32\n\t"
        "addi    t2, t5, 1\n\t"
        /* Estimate the top 32 bits of the quotient. */
        "divu    t0, %[d1], t2\n\t"
        "slli    t4, %[div], 32\n\t"
        "slli    t3, t0, 32\n\t"
        "mul     t1, %[div], t3\n\t"
        "mulhu   t0, %[div], t3\n\t"
        "sltu    a4, %[d0], t1\n\t"
        "sub     %[d0], %[d0], t1\n\t"
        "sub     %[d1], %[d1], t0\n\t"
        "sub     %[d1], %[d1], a4\n\t"
        /* Correct the estimate when the remainder is still too large. */
        "sltu    t6, %[d1], t2\n\t"
        "xori    t6, t6, 1\n\t"
        "slli    a3, t6, 32\n\t"
        "sub     t6, zero, t6\n\t"
        "and     t4, t4, t6\n\t"
        "and     t5, t5, t6\n\t"
        "sltu    a4, %[d0], t4\n\t"
        "sub     %[d0], %[d0], t4\n\t"
        "sub     %[d1], %[d1], t5\n\t"
        "sub     %[d1], %[d1], a4\n\t"
        "add     t3, t3, a3\n\t"
        /* Next 32 bits of the quotient from the top of the remainder. */
        "srli    t0, %[d0], 32\n\t"
        "slli    t1, %[d1], 32\n\t"
        "or      t0, t0, t1\n\t"
        "divu    t0, t0, t2\n\t"
        "add     t3, t3, t0\n\t"
        "mul     t1, %[div], t0\n\t"
        "mulhu   t0, %[div], t0\n\t"
        "sltu    a4, %[d0], t1\n\t"
        "sub     %[d0], %[d0], t1\n\t"
        "sub     %[d1], %[d1], t0\n\t"
        "sub     %[d1], %[d1], a4\n\t"
        /* Next 32 bits of the quotient from the top of the remainder. */
        "srli    t0, %[d0], 32\n\t"
        "slli    t1, %[d1], 32\n\t"
        "or      t0, t0, t1\n\t"
        "divu    t0, t0, t2\n\t"
        "add     t3, t3, t0\n\t"
        "mul     t1, %[div], t0\n\t"
        "mulhu   t0, %[div], t0\n\t"
        "sltu    a4, %[d0], t1\n\t"
        "sub     %[d0], %[d0], t1\n\t"
        "sub     %[d1], %[d1], t0\n\t"
        "sub     %[d1], %[d1], a4\n\t"
        /* Remainder now fits in a word - finish with a plain divide. */
        "divu    t0, %[d0], %[div]\n\t"
        "add     %[d1], t3, t0\n\t"
        : [d1] "+r" (d1), [d0] "+r" (d0), [div] "+r" (div)
        :
        : "memory", "t0", "t1", "t2", "t3", "t4", "t5", "t6", "a3", "a4"
    );
    return (word64)(size_t)d1;
}

/* AND m into each word of a and store in r.
 *
 * @param [out] r  A single precision integer.
 * @param [in]  a  A single precision integer.
 * @param [in]  m  Mask to AND against each digit.
 */
static void sp_4096_mask_64(sp_digit* r, const sp_digit* a, sp_digit m)
{
#ifdef WOLFSSL_SP_SMALL
    int i;

    for (i=0; i<64; i++) {
        r[i] = a[i] & m;
    }
#else
    int i;

    for (i = 0; i < 64; i += 8) {
        r[i+0] = a[i+0] & m;
        r[i+1] = a[i+1] & m;
        r[i+2] = a[i+2] & m;
        r[i+3] = a[i+3] & m;
        r[i+4] = a[i+4] & m;
        r[i+5] = a[i+5] & m;
        r[i+6] = a[i+6] & m;
        r[i+7] = a[i+7] & m;
    }
#endif
}

