/* Map the Montgomery form projective coordinate point to an affine point.
 *
 * @param [out] r  Resulting affine coordinate point.
 * @param [in]  p  Montgomery form projective coordinate point.
 * @param [out] t  Temporary ordinate data.
 */
static void sp_384_map_6(sp_point_384* r, const sp_point_384* p,
    sp_digit* t)
{
    sp_digit* t1 = t;
    sp_digit* t2 = t + 2*6;
    sp_int64 n;

    sp_384_mont_inv_6(t1, p->z, t + 2*6);

    sp_384_mont_sqr_6(t2, t1, p384_mod, p384_mp_mod);
    sp_384_mont_mul_6(t1, t2, t1, p384_mod, p384_mp_mod);

    /* x /= z^2 */
    sp_384_mont_mul_6(r->x, p->x, t2, p384_mod, p384_mp_mod);
    XMEMSET(r->x + 6, 0, sizeof(sp_digit) * 6U);
    sp_384_mont_reduce_6(r->x, p384_mod, p384_mp_mod);
    /* Reduce x to less than modulus */
    n = sp_384_cmp_6(r->x, p384_mod);
    sp_384_cond_sub_6(r->x, r->x, p384_mod, (sp_digit)~(n >> 63));
    sp_384_norm_6(r->x);

    /* y /= z^3 */
    sp_384_mont_mul_6(r->y, p->y, t1, p384_mod, p384_mp_mod);
    XMEMSET(r->y + 6, 0, sizeof(sp_digit) * 6U);
    sp_384_mont_reduce_6(r->y, p384_mod, p384_mp_mod);
    /* Reduce y to less than modulus */
    n = sp_384_cmp_6(r->y, p384_mod);
    sp_384_cond_sub_6(r->y, r->y, p384_mod, (sp_digit)~(n >> 63));
    sp_384_norm_6(r->y);

    XMEMSET(r->z, 0, sizeof(r->z) / 2);
    r->z[0] = 1;
}

/* Add two Montgomery form numbers (r = a + b % m).
 *
 * @param [out] r  Result.
 * @param [in]  a  Number in Montgomery form.
 * @param [in]  m  Modulus (prime).
 */
static void sp_384_mont_add_6(sp_digit* r, const sp_digit* a, const sp_digit* b,
    const sp_digit* m)
{
    __asm__ __volatile__ (
        "ld      t0, 0(%[a])\n\t"
        "ld      t1, 8(%[a])\n\t"
        "ld      t2, 16(%[a])\n\t"
        "ld      t3, 24(%[a])\n\t"
        "ld      t4, 32(%[a])\n\t"
        "ld      t5, 40(%[a])\n\t"
        "ld      t6, 0(%[b])\n\t"
        "add     t0, t0, t6\n\t"
        "sltu    a3, t0, t6\n\t"
        "ld      t6, 8(%[b])\n\t"
        "add     t1, t1, t6\n\t"
        "sltu    a4, t1, t6\n\t"
        "add     t1, t1, a3\n\t"
        "sltu    a5, t1, a3\n\t"
        "or      a3, a4, a5\n\t"
        "ld      t6, 16(%[b])\n\t"
        "add     t2, t2, t6\n\t"
        "sltu    a4, t2, t6\n\t"
        "add     t2, t2, a3\n\t"
        "sltu    a5, t2, a3\n\t"
        "or      a3, a4, a5\n\t"
        "ld      t6, 24(%[b])\n\t"
        "add     t3, t3, t6\n\t"
        "sltu    a4, t3, t6\n\t"
        "add     t3, t3, a3\n\t"
        "sltu    a5, t3, a3\n\t"
        "or      a3, a4, a5\n\t"
        "ld      t6, 32(%[b])\n\t"
        "add     t4, t4, t6\n\t"
        "sltu    a4, t4, t6\n\t"
        "add     t4, t4, a3\n\t"
        "sltu    a5, t4, a3\n\t"
        "or      a3, a4, a5\n\t"
        "ld      t6, 40(%[b])\n\t"
        "add     t5, t5, t6\n\t"
        "sltu    a4, t5, t6\n\t"
        "add     t5, t5, a3\n\t"
        "sltu    a5, t5, a3\n\t"
        "or      a3, a4, a5\n\t"
        "sub     a3, zero, a3\n\t"
        "li      a5, 0\n\t"
        "li      a6, 4294967295\n\t"
        "and     a6, a6, a3\n\t"
        "sltu    a4, t0, a6\n\t"
        "sub     t0, t0, a6\n\t"
        "mv      a5, a4\n\t"
        "li      a6, 18446744069414584320\n\t"
        "and     a6, a6, a3\n\t"
        "sltu    a4, t1, a6\n\t"
        "sub     t1, t1, a6\n\t"
        "sltu    a6, t1, a5\n\t"
        "sub     t1, t1, a5\n\t"
        "or      a4, a4, a6\n\t"
        "mv      a5, a4\n\t"
        "li      a6, 18446744073709551614\n\t"
        "and     a6, a6, a3\n\t"
        "sltu    a4, t2, a6\n\t"
        "sub     t2, t2, a6\n\t"
        "sltu    a6, t2, a5\n\t"
        "sub     t2, t2, a5\n\t"
        "or      a4, a4, a6\n\t"
        "mv      a5, a4\n\t"
        "li      a6, 18446744073709551615\n\t"
        "and     a6, a6, a3\n\t"
        "sltu    a4, t3, a6\n\t"
        "sub     t3, t3, a6\n\t"
        "sltu    a6, t3, a5\n\t"
        "sub     t3, t3, a5\n\t"
        "or      a4, a4, a6\n\t"
        "mv      a5, a4\n\t"
        "li      a6, 18446744073709551615\n\t"
        "and     a6, a6, a3\n\t"
        "sltu    a4, t4, a6\n\t"
        "sub     t4, t4, a6\n\t"
        "sltu    a6, t4, a5\n\t"
        "sub     t4, t4, a5\n\t"
        "or      a4, a4, a6\n\t"
        "mv      a5, a4\n\t"
        "li      a6, 18446744073709551615\n\t"
        "and     a6, a6, a3\n\t"
        "sltu    a4, t5, a6\n\t"
        "sub     t5, t5, a6\n\t"
        "sltu    a6, t5, a5\n\t"
        "sub     t5, t5, a5\n\t"
        "or      a4, a4, a6\n\t"
        "mv      a5, a4\n\t"
        "sd      t0, 0(%[r])\n\t"
        "sd      t1, 8(%[r])\n\t"
        "sd      t2, 16(%[r])\n\t"
        "sd      t3, 24(%[r])\n\t"
        "sd      t4, 32(%[r])\n\t"
        "sd      t5, 40(%[r])\n\t"
        : [r] "+r" (r), [a] "+r" (a), [b] "+r" (b), [m] "+r" (m)
        :
        : "memory", "t0", "t1", "t2", "t3", "t4", "t5", "t6", "a3", "a4", "a5",
            "a6"
    );
}

